import{_ as t}from"./chunks/icon.B7gRmRZx.js";import{_ as o,a,b as n,c as s,d as r,e as i,f as d,g as l,h as c,i as p,j as u}from"./chunks/0.1.12-193-neustart-de.NjH6ArMk.js";import{_ as g,o as h,c as m,a3 as b}from"./chunks/framework.BlfGB29P.js";const H=JSON.parse('{"title":"Logic Studio","description":"Logic Studio 0.1.12 with DE/EN/FR, persisted language selection and block help for Home Assistant.","frontmatter":{"title":"Logic Studio","description":"Logic Studio 0.1.12 with DE/EN/FR, persisted language selection and block help for Home Assistant."},"headers":[],"relativePath":"en/projects/logic-studio/index.md","filePath":"en/projects/logic-studio/index.md","lastUpdated":1794156947000}'),f={name:"en/projects/logic-studio/index.md"};function v(w,e,k,y,_,A){return h(),m("div",null,[...e[0]||(e[0]=[b('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+t+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – public test update, 8 November 2026.</strong> Both interface and documentation now support <strong>DE/EN/FR</strong>. Logic Studio is a standalone HA app for visual function-block plans, independent of Grafik Visual Studio and Blocks for HA. The React Flow canvas retains custom blocks, typed connections, zoom and MiniMap; libraries and licenses are bundled locally.</p><div class="warning custom-block"><p class="custom-block-title">Test release</p><p>Install on a test system first and create a full backup beforehand. Native detail properties currently use JSON. The app does not write automations/scripts back to HA or control devices. Review and install generated output yourself.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">GitHub test release and ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Source in the shared repository</a></p><h2 id="test-installation-from-github" tabindex="-1">Test installation from GitHub <a class="header-anchor" href="#test-installation-from-github" aria-label="Permalink to &quot;Test installation from GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Add repository to Home Assistant"></a></p><ol><li>Under <strong>Settings → Apps → App store → Repositories</strong>, add the URL below. If “UGSo HA Apps” is already configured, check for updates instead.</li><li>Select and install <strong>UGSo Logic Studio</strong>. Enable advanced mode in your HA profile if experimental apps are hidden.</li><li>Start it and open its web UI. Supports <strong>HA OS/Supervised</strong>, <strong>amd64 and aarch64</strong>. The first container build may take several minutes. This is not a HACS/Marketplace frontend package.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Keep an existing local test installation:</strong> GitHub and local apps have different repository IDs and separate data. Export your old plan using <strong>Projekt</strong> as JSON, then use <strong>Öffnen</strong> in the GitHub app. There is no automatic migration or uninstall. Each app retains its project and palette settings under <code>/data</code>.</p><p><strong>Update an existing GitHub app:</strong> Back up first, check for updates in the app manager and choose <strong>UGSo Logic Studio → Update</strong>. Keep the app installed: <code>/data</code>, entity IDs and existing plans are preserved. Do not uninstall or switch app IDs. On .193, the original plan, favorites, recent blocks and collapsed categories remained intact after the update.</p><h2 id="language-toolbar-and-documentation" tabindex="-1">Language, toolbar and documentation <a class="header-anchor" href="#language-toolbar-and-documentation" aria-label="Permalink to &quot;Language, toolbar and documentation&quot;">​</a></h2><p>Choose <strong>Language → Deutsch / English / Français</strong> in the header. Menus, block descriptions, entity picker and import/export dialogs switch without reloading. The choice is saved with browser/app preferences. <strong>Custom names, entity IDs, values, port names and generated YAML/JavaScript code are not translated.</strong></p><p><strong>Documentation</strong> on the right lists implemented keyboard shortcuts and, when a block is selected, its description and input/output ports. <strong>Ctrl+Z / Ctrl+Y</strong>: undo/redo; <strong>Delete</strong>: delete selection; <strong>Esc</strong>: cancel a connection/close a menu. Use Tab and Enter/Space to select and connect ports. Debugger commands from the ioBroker reference editor are not presented as implemented features.</p><p>The toolbar groups <strong>Undo/redo → Project → Simulation → Output</strong>. The three simulation buttons have equal dimensions and separate borders. The project menu also offers <strong>New project</strong> and <strong>Load example</strong>. Open entity selection using the icon <strong>beside HA entity ID</strong> in STATE_IN/STATE_OUT properties; the previous top entity button is removed.</p><p><img src="'+o+'" alt="German documentation view on .193 with the original plan intact"></p><p><img src="'+a+'" alt="English documentation view of the same plan on .193"></p><p><img src="'+n+'" alt="French documentation view of the same plan on .193"></p><h2 id="two-kinds-of-plan" tabindex="-1">Two kinds of plan <a class="header-anchor" href="#two-kinds-of-plan" aria-label="Permalink to &quot;Two kinds of plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan</th><th>Purpose and output</th></tr></thead><tbody><tr><td>Dataflow</td><td>Typed inputs/outputs, logic, math, selection, latches, edges, timers and counters. 33 implemented types; other reference types are marked templates. Export HA automation YAML, HA script YAML or a JavaScript function with a host interface.</td></tr><tr><td>Native HA flow</td><td>Import automations, scripts and blueprints as nested blocks. 53 additional HA types cover triggers, conditions, branches, loops, waits, variables and blueprint inputs. Export native HA YAML only.</td></tr></tbody></table><p>Dataflow simulation uses demo/snapshot values. Persistent blocks need the documented HA text helpers or a JavaScript memory host. Native HA flows are neither executed in the editor nor automatically translated to JavaScript. The JavaScript output is not an ioBroker script.</p><h2 id="drag-connections-and-overview" tabindex="-1">Drag connections and overview <a class="header-anchor" href="#drag-connections-and-overview" aria-label="Permalink to &quot;Drag connections and overview&quot;">​</a></h2><p>Hold the mouse button on a colored pin, drag to a matching opposite pin and release. The cursor becomes a crosshair and a wire preview follows the mouse. Compatible targets are highlighted green; incompatible or occupied inputs are marked red. Dragging from an input back to an output also works. <strong>Esc</strong> or releasing on empty canvas cancels; <strong>Undo</strong> removes a newly created wire.</p><p><strong>BOOL connects only to BOOL.</strong> Identical signal types are compatible, with additional <code>INT → REAL</code> widening. Explicit <code>ANY</code> pins are universal. Numbers and text are not silently converted to BOOL. Each input accepts exactly one wire; incompatible types, matching pin directions, self-connections and cycles are rejected with an explanation. For keyboard operation, select the output with Tab/Enter, then select the input and press Enter.</p><p><img src="'+s+'" alt="Compatible BOOL pins connected by mouse on .193"></p><p><img src="'+r+'" alt="STRING to BOOL is rejected with a clear type error"></p><p>The bottom-right <strong>MiniMap</strong> shows colored block positions and the visible viewport. Drag inside it to navigate and use the wheel to zoom. Drag empty canvas to pan; <strong>+/−</strong> change the zoom and <strong>Alles anzeigen</strong> fits all blocks. Drag a block by its header. The <strong>React Flow</strong> attribution remains visible at the bottom right. Since 0.1.8 the library actually runs in the editor; domain logic, type validation and exporters remain independent Logic Studio components.</p><p><img src="'+i+'" alt="React Flow canvas with preserved original plan and MiniMap on .193"></p><p><img src="'+d+'" alt="Local React Flow test with typed blocks"></p><p>The following images additionally document the earlier 0.1.7 tests.</p><p><img src="'+l+'" alt="Overview with block positions and visible viewport on .193"></p><h2 id="import-and-editing" tabindex="-1">Import and editing <a class="header-anchor" href="#import-and-editing" aria-label="Permalink to &quot;Import and editing&quot;">​</a></h2><p>Open <strong>HA importieren</strong>, choose automations/scripts/blueprints, and use <strong>Aus HA einlesen</strong>, a YAML/JSON file or pasted text. Select an entry, review its preview, then choose <strong>Import übernehmen</strong>. Save your existing plan as JSON first; project and source-file backups are also created.</p><p>The HA configuration mount is <strong>read-only</strong>. The app reads <code>automations.yaml</code>, <code>scripts.yaml</code> and blueprint files. Before parsing, sources are copied to <code>/data/ha-source-backups/&lt;timestamp&gt;/</code> using their original names. <code>secrets.yaml</code> is not opened; <code>!secret</code> and <code>!include</code> remain unresolved. Import referenced include files manually.</p><p>Orange <strong>FLOW</strong> wires represent execution order and branches: branch output → <strong>DO</strong>, then <strong>NEXT → DO</strong>. Yellow <strong>VALUE/REF</strong> wires show blueprint parameters and their <code>!input</code> usage. Properties contain HA configuration and branch paths as JSON. Parameter/field keys must be unique. Unknown sections remain <strong>YAML_ORIGINAL</strong>; missing wires can block export.</p><p><img src="'+c+'" alt="Import preview of existing HA blueprints"></p><p>Each block’s <strong>⋮ menu</strong> offers <strong>Eigenschaften</strong> (properties), <strong>Duplizieren</strong> (duplicate) and <strong>Löschen</strong> (delete). Duplication copies properties without wires. Deletion removes associated wires; undo restores them. Search, favorites and recently used blocks help navigation.</p><p><img src="'+p+'" alt="Per-block three-dot menu"></p><h2 id="validation-and-limits" tabindex="-1">Validation and limits <a class="header-anchor" href="#validation-and-limits" aria-label="Permalink to &quot;Validation and limits&quot;">​</a></h2><p><strong>0.1.12 on .193 / HA Core 2026.10.4:</strong> Updated the local app from 0.1.8 after a full backup. DE/EN/FR, documentation and real HA entity selection passed. French survived browser reload, app restart and loading the saved app project again; German was restored afterwards. Project JSON differs <strong>only in version</strong>: all five blocks, three connections, names, values and positions are identical. Generated YAML is identical in EN and FR. No devices controlled. <strong>31 Node and nine Python tests</strong> passed. Older reports below remain as history.</p><p><img src="'+u+'" alt="German restored after the successful app restart on .193"></p><p><strong>0.1.8 on .193 / HA Core 2026.10.4:</strong> Updated the existing local app after a full backup. Typed mouse connections, STRING→BOOL rejection, occupied inputs, move/undo, duplicate, zoom and MiniMap passed. The entity picker reads HA entities; a nested script with If/Then/Else, Delay and Stop was imported and exported with its structure preserved. The original plan was restored and compared after reload: <strong>all IDs, positions, parameters and three wires unchanged</strong>, along with favorites, recent blocks and collapsed categories. No devices were controlled. Docker build and container HTTP smoke test passed, as did <strong>29 Node and eight Python tests</strong>. Screenshots show the German UI. Light/dark switching was not manually retested in this step.</p><p>The <strong>0.1.5</strong> functional baseline was tested on <strong>.193 / HA Core 2026.10.4</strong>: actual blueprint import, automation/script/blueprint fixtures, semantically identical YAML exports and menu actions. <strong>0.1.6</strong> is its first public packaging. 22 Node and eight Python tests cover export, persistence, nested flows and safe source import; GitHub checks also build the container.</p><p><strong>0.1.7 on .193 / HA Core 2026.10.4:</strong> Real mouse-drag tests passed for BOOL → BOOL and the reverse direction. STRING → BOOL and an occupied input were rejected. Overview, click navigation and Home were verified. The original plan was restored and compared with its backup: <strong>five blocks, three wires and all palette preferences preserved</strong>, including after the local update to 0.1.7. Full HA and separate plan/settings backups were created first; no devices were controlled. <strong>26 Node and eight Python tests</strong> currently pass. Screenshots show the German UI.</p><p>The editor does not provide complete HA semantic validation: verify targets, templates and selectors in HA. Comments, YAML anchors and formatting are not reconstructed. Import limits: <strong>1 MB, 200 blocks, 500 wires</strong>, bounded nesting and up to 250 blueprint files in standard folders. Controllers, calendar and custom subplans partly remain templates.</p><p>For local tests, extract the entire release ZIP, install Python 3.10+ and <code>requirements.txt</code>, then run <strong>Start-Demo.cmd</strong> on Windows. <code>http://127.0.0.1:4180/</code> shows demo entities without connecting to HA. The ZIP also contains <code>addon/logic_studio/</code> for local app installations.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">Report issues on GitHub</a> with versions, architecture and a minimal anonymized example. Do not publish credentials, personal automations or full backups. Further guides and the test report are included. MIT license; extracted block metadata attribution is in <code>THIRD-PARTY.txt</code>.</p>',46)])])}const L=g(f,[["render",v]]);export{H as __pageData,L as default};
